def _trust_page(prop: str, typ: str, title: str) -> str:
    scope = DESK_SCOPE[prop]
    paras = []
    for h, b in TYPE_BODY[typ]:
        paras.append(f"<h3>{h}</h3><p>{b}</p>")
    desk_paras = (
        f"<h3>This desk specifically</h3><p>On this site, {scope} The pages on this desk are written by the same editorial process that governs the whole site: sourced claims, dated figures and dated verdicts, applied here to {prop}-desk subject matter.</p>"
        f"<p>The desk-specific pages on this site \u2014 the guides, reviews and tools under the {prop} section \u2014 each carry their own method notes and review dates. Where a policy on this page and a practice on an individual page disagree, the individual page\u2019s dated note is the specific record and this page is the general one.</p>"
    )
    list_items = {
        "about": ["Sourced claims, dated figures and dated verdicts", "No sponsored placements and no pay-to-play verdicts", "Published corrections with dated notes", "Method notes on every measured page", "Funding disclosed: the desk is funded by its own operators", "Reviews dated at the verdict line, always"],
        "terms": ["Personal, non-commercial use with attribution for quotes", "No professional advice is created by reading any page", "Tools for individual use; bulk use by permission", "Terms dated and reviewed on the editorial calendar", "Unenforceable provisions do not void the rest", "Questions answered through the contact route"],
        "contact": ["Real inbox, real answers, usually within a working week", "Corrections jump the queue and are checked against sources", "No individual professional advice by reply", "Press and pitches welcome; pay-to-play is not", "Material corrections logged publicly with dates", "Named in the correction note if the sender wishes"],
        "corrections": ["Errors fixed at the point of error with a dated note", "Material errors flagged at the top of the page", "Corrections verified against primary sources", "Disagreements and updates kept out of the error log", "Log reviewed on the editorial calendar", "Senders of good corrections credited on request"],
        "copyright": ["Content protected as published; all rights reserved", "Short attributed extracts and links welcome", "Commercial republication needs written permission", "Third-party marks used for identification only", "Permission requests answered with real terms", "Genuine notices actioned promptly and in good faith"],
        "disclaimer": ["General information dated at the page level", "No legal, financial, medical or engineering advice", "Prices and rules carry their verification dates", "External links cited for the facts they support", "Professional judgement for real stakes, always", "Rights that cannot be limited are not limited"],
        "editorial-policy": ["Primary sources over secondary, every time", "Claims, sources and dates travel together", "Published scoring method applied consistently", "Access disclosed beside every verdict", "Corrections logged publicly with dated notes", "Shelf-life facts re-checked on the editorial calendar"],
        "subscriptions": ["Plain-language terms: price, period, deliverable", "Renewal date visible, never hidden", "Cancellation at period end; clean pro-rata refunds", "Subscriber data minimised and never sold", "Real support answers to billing questions", "Terms reviewed with the same date discipline as editorial"],
        "methodology": ["Measurement method published beside every figure", "Figures dated and re-checked on the calendar", "Review scores marked with their method version", "External sources verified live before publication", "Failure record kept and published", "Ranges published honestly instead of false decimals"],
        "buying": ["Criteria first, products second in every guide", "Prices dated at verification; drift is expected", "Testing labelled separately from research guides", "Commercial arrangements disclosed beside products", "Guides dated and reviewed on the editorial calendar", "Method and date let a reader judge the guide\u2019s currency"],
    }[typ]
    lis = "".join(f"<li>{i}</li>" for i in list_items)
    topic = typ.replace("-", " ")
    return (f"<h2>{title}</h2>" + "".join(paras) + desk_paras +
            f"<h3>The working list</h3><ul>{lis}</ul>"
            f'<p>Background context for this page is cross-checked against <a href="https://en.wikipedia.org/wiki/Special:Search?search={topic.replace(" ", "+")}" rel="noopener">the encyclopaedic record</a> where a reference helps. '
            f"The desk\u2019s standard applies across the archive: named entities carry sources, measured figures carry dates and claims the desk cannot verify are marked rather than rounded. Policies are only as good as their practice, and the practice on this site is public: the pages carry their dates, the corrections carry their notes and the review cycle is a calendar rather than a mood. A reader who finds the practice and the policy disagreeing should write to the desk through the contact page \u2014 that message is the most useful one the desk receives, and it is answered. Reviewed 2026-09-28.</p>")

